async function loadPdfFonts(){if(!pdfFontsPromise)pdfFontsPromise=Promise.all(['Regular','Bold'].map(async weight=>{const r=await fetch('fonts/Lato-'+weight+'.ttf');if(!r.ok)throw Error('Fonte indisponível');const bytes=new Uint8Array(await r.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)})).catch(e=>{pdfFontsPromise=null;throw e});return pdfFontsPromise}
async function exportPDF(){if(!DATABASE||!shown.length)return;const s=snapshot(),kind=state.view;pdfExportBusy=true;syncExportMenu();try{const fonts=await loadPdfFonts();const doc=AtlasPDF.create({jsPDF:window.jspdf.jsPDF,fonts,snapshot:s,kind});doc.save(`${s.kind}-${s.year}-${s.mode.toLowerCase()}-${kind==='chart'?'grafico':'tabela'}.pdf`);toast('PDF gerado com '+s.rows.length+' registros.')}catch(error){toast('Não foi possível gerar o PDF. Tente novamente.');console.error(error)}finally{pdfExportBusy=false;syncExportMenu()}}
function syncExportMenu(){const visual=state.view==='table'?'Tabela':'Gráfico';$('#export-target').textContent=visual+' selecionad'+(state.view==='table'?'a':'o');$('#export-pdf-label').textContent=visual+' em PDF';$('#export-menu-note').textContent=shown.length+' registros · '+state.year+' · '+presentationLabel(presentationPreference().preset);$('#export-toggle').disabled=pdfExportBusy||!DATABASE||!shown.length;$('#export-toggle').innerHTML=pdfExportBusy?'Gerando PDF…':'Exportar <span aria-hidden="true">↓</span>';$('#export-pdf').disabled=pdfExportBusy||!shown.length;$('#csv').disabled=pdfExportBusy||!shown.length}
function closeExportMenu(focus=false){$('#export-menu').hidden=true;$('#export-toggle').setAttribute('aria-expanded','false');if(focus)$('#export-toggle').focus()}
function openExportMenu(focus=false){if($('#export-toggle').disabled)return;syncExportMenu();$('#export-menu').hidden=false;$('#export-toggle').setAttribute('aria-expanded','true');if(focus)$('#export-pdf').focus()}
$('#export-toggle').addEventListener('click',()=>$('#export-menu').hidden?openExportMenu():closeExportMenu());$('#export-toggle').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();openExportMenu(true);if(e.key==='ArrowUp')$('#csv').focus()}});
$('#export-menu').addEventListener('keydown',e=>{const items=[$('#export-pdf'),$('#csv')],index=items.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(index+(e.key==='ArrowDown'?1:items.length-1))%items.length].focus()}if(e.key==='Home'){e.preventDefault();items[0].focus()}if(e.key==='End'){e.preventDefault();items.at(-1).focus()}if(e.key==='Escape'){e.preventDefault();closeExportMenu(true)}if(e.key==='Tab')closeExportMenu()});
$('#export-pdf').addEventListener('click',()=>{closeExportMenu(true);exportPDF()});
$('#csv').addEventListener('click',()=>{if(!DATABASE)return;const s=snapshot();const head=isStats()?['edicao','territorio','area','participantes','media','mediana','moda','minimo','maximo','desvio_padrao','contagem','valor_exibido','unidade','tabela','fonte']:['exame','edicao','modalidade','posicao','codigo','carreira_curso','campus','instituicao','uf','grau','turno','descricao_modalidade','bonus','corte_pontos','base_percentual','base_historica_da_carreira','vagas','inscritos_ou_inscricoes','por_vaga','fonte','arquivo_obtido','etapa','classificacao_publicada','pagina_fonte'];const rows=shown.map(r=>isStats()?[r.year||s.year,state.geo,r.label,r.n,r.mean,r.median,r.mode,r.min,r.max,r.sd,r.count,r.cut,unit(),r.table,r.source||s.source]:[isSisu()?r.processName:s.exam,isSisu()?r.year:s.year,isSisu()?r.mode:s.mode,r.rank,isSisu()?r.courseCode:r.code,r.label,r.campus,r.institution,r.uf,r.degree,r.shift,r.modeDescription,r.bonus,r.cut,edition.questions??'',r.sourceBase,r.vacancies,r.applicants,ratio(r),isSisu()?r.source:s.source,isSisu()?r.download:s.download,r.stage,r.admissionRank,r.sourcePage]);const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[head,...rows].map(row=>row.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=type()+'-'+s.year+'-dados.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeExportMenu(true);toast(shown.length+' registros exportados.')});
function presentationContext(){const stats=isStats();return {kind:stats?'stats':isSisu()?'sisu':'fuvest',ranking:state.ranking,axis:state.axis,questions:canNormalize()?edition.questions:null,unit:unit(),countOnly:stats&&statInfo().countOnly,frequency:stats&&statInfo().frequency,statLabel:stats?statInfo().label:null,metricName:stats?statInfo().metric:'Corte'}}
function presentationLabel(preset){return {essential:'Essencial',detailed:'Detalhada',custom:'Personalizada'}[preset]||'Essencial'}
function presentationPreference(){
 const key=AtlasPresentation.key(presentationContext());
 if(presentationParamsPending){presentationParamsPending=false;if(params.has('detail'))presentationPreferences[key]={preset:['essential','detailed','custom'].includes(params.get('detail'))?params.get('detail'):'essential',fields:(params.get('fields')||'').split(',').filter(Boolean)}}
 const pref=presentationPreferences[key];return pref&&['essential','detailed','custom'].includes(pref.preset)?pref:{preset:'essential',fields:[]};
}
function renderPresentation(){
 const context=presentationContext(),pref=presentationPreference(),resolved=AtlasPresentation.resolve(context,eligible,pref);
 currentPresentation=AtlasPresentation.model(context,shown,resolved);$('#customize-view').disabled=false;
 $('#presentation-state').hidden=pref.preset==='essential';$('#presentation-state').textContent=presentationLabel(pref.preset);$('#customize-view').setAttribute('aria-label','Personalizar visualização · '+presentationLabel(pref.preset));
}
function refreshPresentationChoices(){
 const resolved=AtlasPresentation.resolve(presentationContext(),eligible,presentationDraft),selected=new Set(resolved.selected.map(f=>f.id));
 $$('[name="presentation-preset"]').forEach(r=>r.checked=r.value===presentationDraft.preset);
 $('#presentation-count').textContent=selected.size?' · '+selected.size:'';
 $('#presentation-fields').replaceChildren(...resolved.fields.map(f=>{
  const label=document.createElement('label');label.className='presentation-field';const input=document.createElement('input');input.type='checkbox';input.value=f.id;input.checked=selected.has(f.id);input.disabled=!f.available&&!input.checked;
  const copy=document.createElement('span'),name=document.createElement('strong');name.textContent=f.label;copy.append(name);
  if(!f.available){const note=document.createElement('small');note.textContent='Sem valores incorporados neste recorte';copy.append(note)}
  input.addEventListener('change',()=>{const fields=new Set(AtlasPresentation.resolve(presentationContext(),eligible,presentationDraft).selected.map(v=>v.id));if(input.checked)fields.add(f.id);else fields.delete(f.id);presentationDraft={preset:'custom',fields:[...fields]};refreshPresentationChoices()});label.append(input,copy);return label;
 }));
 $('#presentation-preview').textContent=resolved.fields.length?(selected.size?selected.size+' '+(selected.size===1?'informação adicional':'informações adicionais')+' · Linhas no gráfico e colunas na tabela.':'Somente o valor principal e o contexto necessário.'):'Este recorte já apresenta todas as informações disponíveis.';
}
$('#customize-view').addEventListener('click',()=>{closeExportMenu();presentationDraft=JSON.parse(JSON.stringify(presentationPreference()));$('#presentation-choices').open=presentationDraft.preset==='custom';refreshPresentationChoices();$('#presentation-dialog').showModal()});
$$('[name="presentation-preset"]').forEach(input=>input.addEventListener('change',()=>{presentationDraft={preset:input.value,fields:[]};refreshPresentationChoices()}));
for(const id of ['close-presentation','cancel-presentation'])$('#'+id).addEventListener('click',()=>$('#presentation-dialog').close());
$('#apply-presentation').addEventListener('click',()=>{presentationPreferences[AtlasPresentation.key(presentationContext())]=presentationDraft;try{localStorage.setItem('atlas-presentation',JSON.stringify(presentationPreferences))}catch{}$('#presentation-dialog').close();render();toast('Visualização atualizada. O PDF seguirá esta configuração.')});
loadActive();

function renderStatsSummary(){const box=$('#stat-summary');box.hidden=!isStats();if(!isStats())return;const info=statInfo();const items=[['Recorte',state.exam==='fuvest'?'QASE · inscritos':state.geo],['Cobertura',state.statView==='history'?'2009–'+state.year:state.statView==='enrollHistory'?'1998–'+state.year:state.year],['Medida',info.metric],['Registros',String(shown.length)]];box.innerHTML=items.map(([label,value])=>'<div><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>').join('');}

// Explain missing values without presenting them as zero or as a source absence.
function infoSources(source){
 if(source)return [{label:'Fonte da informação',url:source}];
 if(edition?.sources)return edition.sources.flatMap(s=>[{label:s.processName+' '+s.year+' · fonte',url:s.source},...(s.download?[{label:s.processName+' '+s.year+' · arquivo de dados',url:s.download}]:[])]).filter(s=>s.url);
 return edition?.source?[{label:'Documento do recorte selecionado',url:edition.source}]:[];
}
function openInformation(message,sources,context){
 $$('.info-tooltip[popover]').forEach(t=>{if(t.matches(':popover-open'))t.hidePopover()});hideOptionHelp();
 $('#info-dialog-text').textContent=message;$('#info-dialog-context').textContent=context;
 const links=sources.filter((s,i,a)=>a.findIndex(x=>x.url===s.url)===i);
 $('#info-dialog-sources').replaceChildren(...links.map(s=>{const a=document.createElement('a');a.href=s.url;a.target='_blank';a.rel='noopener';a.textContent=s.label+' ↗';return a}));
 if(!links.length)$('#info-dialog-sources').textContent='Nenhum documento associado a esta informação.';
 $('#info-dialog').showModal();
}
function dataInfo(message,source){
 const wrap=document.createElement('span');wrap.className='data-info';
 const button=document.createElement('button');button.type='button';button.className='info-trigger';button.textContent='i';button.setAttribute('aria-label','Abrir informações: '+message);button.setAttribute('aria-haspopup','dialog');
 const tip=document.createElement('span');tip.className='info-tooltip';tip.setAttribute('role','tooltip');tip.setAttribute('popover','manual');tip.textContent=message.length>220?message.slice(0,200).replace(/\s+\S*$/,'')+'… Clique para detalhes.':message;
 const sources=infoSources(source),context=isSisu()?edition.sources.map(s=>s.processName+' '+s.year).join(' · '):(state.exam==='fuvest'?'FUVEST':'ENEM')+' · '+state.year;
 let timer,suppressHover=false;const hide=()=>{clearTimeout(timer);if(tip.matches(':popover-open'))tip.hidePopover()};const show=()=>{clearTimeout(timer);if(!$('#info-dialog').open&&!tip.matches(':popover-open'))tip.showPopover()};
 button.addEventListener('mouseenter',()=>{if(!suppressHover)show()});wrap.addEventListener('mouseleave',()=>{suppressHover=false;timer=setTimeout(hide,120)});tip.addEventListener('mouseenter',()=>clearTimeout(timer));tip.addEventListener('mouseleave',hide);button.addEventListener('blur',hide);
 button.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});
 button.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();suppressHover=true;hide();openInformation(message,sources,context)});
 wrap.append(button,tip);return wrap;
}
$('#close-info').addEventListener('click',()=>$('#info-dialog').close());
function containSelectOptions(select){
 if(!CSS.supports('appearance','base-select')||select.querySelector(':scope > .picker-options'))return;
 const group=document.createElement('optgroup');group.className='picker-options';group.label='';
 group.append(...select.children);select.append(group);
}

function renderDataFeedback(){
 const stats=isStats(),sisu=isSisu();
 renderProcessIdentity();
 const context=stats?(state.exam==='fuvest'?'FUVEST · Perfil dos inscritos':'ENEM · '+($('#stat-view option:checked')?.textContent||'Estatísticas')):state.exam==='fuvest'?'FUVEST · Cortes da primeira fase':admissionsLabel()+' · Notas de ingresso';
 $('#explore-feedback').textContent=context;
 const hasRows=stats?statInfo().rows.some(r=>Number.isFinite(r.cut)):sisu?edition.records.length>0:edition.careers.length>0;
 const missingReason=stats?(statInfo().note||'Esta medida ainda não tem dados validados nesta base. Isso não significa que a fonte nunca os publicou.') : sisu?edition.sources.filter(s=>s.status==='unavailable').map(s=>s.processName+' '+s.year+': '+s.provenance).join(' ')||'A base desta edição ainda não tem ofertas incorporadas.':edition.note||'A tabela desta edição ainda não foi incorporada e validada.';
 const coverage=$('#coverage-info');coverage.replaceChildren(dataInfo($('#coverage-note').textContent||missingReason));
 const emptyInfo=$('#empty-info');emptyInfo.replaceChildren();
 if(!hasRows){$('#empty strong').textContent='Dados ainda não disponíveis neste recorte.';$('#empty-help').textContent='Veja o motivo no ícone de informação e consulte a fonte ou outra edição.';emptyInfo.append(dataInfo(missingReason));}
 else if(!shown.length){$('#empty strong').textContent='Nenhum resultado com estes filtros.';$('#empty-help').textContent='Há dados nesta edição. Limpe os filtros ou revise a busca e a modalidade.';emptyInfo.append(dataInfo('Os filtros atuais não encontraram registros. Isso não indica ausência de dados na fonte.'));}
 $('#clear-search').hidden=!hasRows;$('#clear-search').textContent='Limpar busca e filtros';
 for(const td of $$('#table-body td'))if(td.textContent==='—'){td.append(' ',dataInfo('Valor não informado ou não incorporado nesta fonte e edição. Não foi estimado nem convertido em zero.'));}
 const filterInfo=$('#filter-data-info');filterInfo.replaceChildren();
 if(stats&&state.exam==='enem'&&+state.year<2009)filterInfo.append(dataInfo('Esta edição tem inscrições por estado, região e ano. As notas por área, os perfis e as distribuições anteriores a 2009 ainda não foram incorporados; a estrutura da prova era diferente.'));
 if(sisu&&edition.sources.some(s=>s.process==='sisu'&&+s.year<=2018))filterInfo.append(dataInfo('Os relatórios SiSU de 2010–2018 desta base não informam UF, município, vagas ou inscrições. Consulte as ofertas por instituição ou curso.'));
}

function editionGapNote(source){return source.process==='enem-usp'&&source.year==='2023'?'2023 foi a primeira edição do ENEM-USP. A tabela final da 1ª chamada ainda não foi validada nesta base. Encontramos tabelas provisórias, anteriores ao resultado, que não entram neste gráfico.':source.provenance}
function configureProcessYears(){
 const sources=Object.entries(DATABASE).filter(([y])=>y!=='all').flatMap(([,e])=>e.sources);
 for(const [process,key,id] of [['sisu','sisuYear','sisu-year'],['enem-usp','uspYear','usp-year']]){
  const available=sources.filter(s=>s.process===process).sort((a,b)=>b.year.localeCompare(a.year));
  if(!available.some(s=>s.year===state[key]))state[key]=available.find(s=>s.file)?.year||available[0]?.year;
  setOptions($('#'+id),available.map(s=>[s.year,s.year+(s.file?'':' ⓘ'),s.file?null:{note:editionGapNote(s)}]),state[key]);
 }
 if(state.process==='both'){
  if(state.year!=='all'){for(const key of ['sisuYear','uspYear'])if(sources.some(s=>s.year===state.year&&s.process===(key==='sisuYear'?'sisu':'enem-usp')))state[key]=state.year;}
  const selected=sources.filter(s=>s.year===(s.process==='sisu'?state.sisuYear:state.uspYear));
  DATABASE.all={sources:selected,label:selected.map(s=>s.processName+' '+s.year).join(' + '),records:[]};state.year='all';
  $('#sisu-year').value=state.sisuYear;$('#usp-year').value=state.uspYear;
 }
}
for(const [id,key] of [['sisu-year','sisuYear'],['usp-year','uspYear']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;state.year='all';state.search='';loadActive()});
function renderSidebarSummaries(){
 $('#group-filters-preview').textContent=isStats()?(state.exam==='fuvest'?$('#profile-key option:checked')?.textContent:$('#stat-view option:checked')?.textContent):state.mode+(state.uf?' · '+state.uf:'')+(state.course?' · '+state.course:'');
 $('#group-selection-preview').textContent='Top '+state.count+' · '+(state.ranking==='ratio'?'Inscrições/vaga':'Maiores cortes');
 $('#group-comparison-preview').textContent=refLabel();
 $('#admission-years-note').hidden=!isSisu();
 if(isSisu()){$('#admission-years-summary').textContent='Sobre os dados';$('#admission-years-summary').setAttribute('aria-label','Sobre os dados, processos e edições selecionadas');}
}

function renderProcessIdentity(){
 const active=isSisu();$('#process-coverage-info').hidden=true;$('#process-legend').hidden=!active;
 if(!active)return;
 const processes=state.process==='both'?['sisu','enem-usp']:[state.process];
 $('#process-coverage-info').replaceChildren();
 for(const id of ['sisu-year','usp-year','year']){const label=$('#'+id).closest('label');label.querySelector('.year-coverage-info')?.remove();const process=id==='sisu-year'?'sisu':id==='usp-year'?'enem-usp':state.process;if(process==='both')continue;const info=ENEMAdmissions.coverage[process];const source=edition.sources.find(s=>s.process===process);const message=info.text+(!source?.file&&source?.provenance?' Nesta edição: '+source.provenance:'');const icon=dataInfo(message,info.source);icon.classList.add('year-coverage-info');$('#'+id).setAttribute('aria-label',id==='year'?label.querySelector('span').firstChild.textContent.trim():'Edição do '+info.name);label.querySelector('span').append(' ',icon);}

 $('#process-legend').innerHTML=processes.map(p=>`<span><i class="process-symbol" data-process="${p}" aria-hidden="true"></i>${esc(ENEMAdmissions.coverage[p].name)}</span>`).join('');
}

const optionHelp=document.createElement('div');optionHelp.id='selector-option-info';optionHelp.className='selector-option-info';optionHelp.setAttribute('role','tooltip');optionHelp.setAttribute('popover','manual');document.body.append(optionHelp);
function hideOptionHelp(){if(optionHelp.matches(':popover-open'))optionHelp.hidePopover();optionHelp.hidden=true}
function showOptionHelp(option){if(!option?.dataset.note){hideOptionHelp();return}optionHelp.textContent=option.dataset.note;optionHelp.hidden=false;const rect=option.getBoundingClientRect(),width=Math.min(320,innerWidth-32);optionHelp.style.width=width+'px';optionHelp.style.left=Math.max(16,Math.min(innerWidth-width-16,rect.right+10))+'px';optionHelp.style.top=Math.max(16,Math.min(innerHeight-210,rect.top))+'px';if(typeof optionHelp.showPopover==='function'&&!optionHelp.matches(':popover-open'))optionHelp.showPopover()}
for(const select of $$('select')){select.addEventListener('pointerover',e=>showOptionHelp(e.target.closest('option')));select.addEventListener('focusin',e=>{if(e.target.matches('option'))showOptionHelp(e.target)});for(const event of ['pointerleave','change','blur'])select.addEventListener(event,hideOptionHelp);select.addEventListener('keydown',e=>{if(e.key==='Escape')hideOptionHelp()})}

function animateModeChange(){
 const next=JSON.stringify([state.exam,state.section,state.process,state.year,state.sisuYear,state.uspYear,state.mode,state.view,state.ranking,state.geo,state.statView,state.statMetric,state.statArea,state.profileKey]);
 if(next===visualModeKey)return;
 const first=visualModeKey===null;visualModeKey=next;modeMotion.forEach(a=>a.cancel());modeMotion=[];
 if(first||reduceMotion.matches)return;
 const panel=$(state.view==='table'?'#table-view':'#chart-view');
 modeMotion.push(panel.animate([{opacity:0,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:320,easing:'cubic-bezier(.2,0,0,1)'}));
 modeMotion.push($('#chart-title').animate([{opacity:.35},{opacity:1}],{duration:280,easing:'cubic-bezier(.2,0,0,1)'}));
}

